import { readFileSync, writeFileSync } from 'node:fs';
import type { DomainFile } from '../src/content/types';
import { BOSS_ART } from '../src/art/bossArt';
import { DOMAINS } from './content/structure';

// Writes content/planning/BOSS_ART.md from the accessory registry and the parsed playbooks.
export function bossArtDoc(): string {
  const out = [
    '# Boss art',
    '',
    'Generated by `npx tsx scripts/boss-art-doc.ts` from `src/art/bossArt.ts` and `content/json`. Do not edit by hand.',
    '',
    'Each boss is drawn in the same simple stick style (BUILD_PLAN 19.6). Props come only from the BOSS line in its playbook, or the ART line for final bosses. Figures of religious or historical people get at most a neutral prop named in the playbook, with no caricature and no religious symbols.',
    '',
  ];
  for (const spec of DOMAINS) {
    const file: DomainFile = JSON.parse(readFileSync(`content/json/${spec.id}.json`, 'utf8'));
    out.push(`## ${file.domain.title}`, '', '| Boss | BOSS line | Pose | Expression | Drawn with | Note |', '| --- | --- | --- | --- | --- | --- |');
    for (const b of [...file.units.map((u) => u.miniBoss), file.domain.finalBoss]) {
      const art = BOSS_ART[b.id];
      const drawn = art
        ? [...art.props.map((p) => (p.label ? `${p.key} ("${p.label}")` : p.key)), art.head && art.head !== 'face' ? `${art.head} head` : '', art.body && art.body !== 'ink' ? `${art.body} body` : '', art.scale ? `drawn ${art.scale} times larger` : '']
            .filter(Boolean)
            .join(', ') || 'pose only'
        : 'MISSING';
      const name = b.alwaysEscalate ? `${b.name} (final)` : b.name;
      out.push(`| ${name} | ${b.persona.replace(/\|/g, '/')} | ${art?.pose ?? ''} | ${art?.expression ?? ''} | ${drawn} | ${art?.note ?? ''} |`);
    }
    out.push('');
  }
  return out.join('\n');
}

if (process.argv[1]?.endsWith('boss-art-doc.ts')) {
  writeFileSync('content/planning/BOSS_ART.md', bossArtDoc());
  console.log('Wrote content/planning/BOSS_ART.md');
}
